import re

_HEXDIGITS = set('0123456789abcdefABCDEF')


def _decode_component(s: str) -> str:
    """Decode a single query-string component: '+' -> space, %XX -> byte,
    then interpret resulting bytes as UTF-8."""
    # First replace '+' with space (literal '+' characters, not part of %XX)
    s = s.replace('+', ' ')

    result = bytearray()
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '%':
            # need two more characters for hex digits
            if i + 2 >= n:
                raise ValueError(f"Malformed percent-escape in query string: {s!r}")
            h1, h2 = s[i + 1], s[i + 2]
            if h1 not in _HEXDIGITS or h2 not in _HEXDIGITS:
                raise ValueError(f"Malformed percent-escape in query string: {s!r}")
            result.append(int(h1 + h2, 16))
            i += 3
        else:
            result.extend(c.encode('utf-8'))
            i += 1

    try:
        return bytes(result).decode('utf-8')
    except UnicodeDecodeError as e:
        raise ValueError(f"Invalid UTF-8 sequence in query string: {s!r}") from e


def parse_query(qs: str) -> dict:
    result: dict[str, list[str]] = {}

    for pair in qs.split('&'):
        if pair == '':
            continue  # ignore empty pairs from '&&' or trailing '&'

        if '=' in pair:
            raw_key, raw_value = pair.split('=', 1)
        else:
            raw_key, raw_value = pair, ''

        key = _decode_component(raw_key)
        value = _decode_component(raw_value)

        result.setdefault(key, []).append(value)

    return result


# --- visible example checks ---
assert parse_query('a=1&b=2&a=3') == {'a': ['1', '3'], 'b': ['2']}
assert parse_query('q=hello+world') == {'q': ['hello world']}
